class _FakeAsyncioNamespace:
    """Stands in for the `asyncio` name inside scheduler.py only — the real
    asyncio module elsewhere is untouched, since this replaces one attribute
    binding on the scheduler module object, not the shared asyncio module."""

    CancelledError = asyncio.CancelledError

    @staticmethod
    def create_task(coro, name=None):
        return asyncio.create_task(coro)

    @staticmethod
    async def sleep(_seconds):
        return None


class _ScriptedDatetime:
    """`datetime.now(tz=...)` stand-in: returns queued values, then raises
    CancelledError to end the otherwise-infinite _scheduled_job() loop."""

    def __init__(self, queue):
        self._queue = list(queue)

    def now(self, tz=None):
        if not self._queue:
            raise asyncio.CancelledError("scripted clock exhausted — ending test loop")
        value = self._queue.pop(0)
        return value.astimezone(tz) if tz else value


@pytest.fixture
def fast_clock(monkeypatch):
    monkeypatch.setattr(sched, "asyncio", _FakeAsyncioNamespace())

    def _install(queue):
        monkeypatch.setattr(sched, "datetime", _ScriptedDatetime(queue))

    return _install


