def test_start_scheduler_returns_none_when_disabled(monkeypatch):
    # Unit 10: two independent gates now start the loop -- both must be off.
    monkeypatch.setattr(sched, "PTA_SCHEDULER_ENABLED", False)
    monkeypatch.setattr(sched, "IB_INGEST_ENABLED", False)
    assert sched.start_scheduler() is None


def test_start_scheduler_returns_task_when_enabled(monkeypatch):
    monkeypatch.setattr(sched, "PTA_SCHEDULER_ENABLED", True)
    monkeypatch.setattr(sched, "asyncio", _FakeAsyncioNamespace())

    async def _run():
        task = sched.start_scheduler()
        assert isinstance(task, asyncio.Task)
        task.cancel()
        try:
            await task
        except asyncio.CancelledError:
            pass

    asyncio.run(_run())


def test_start_scheduler_default_is_disabled_without_env_override():
    # Import-time default per the contract: PTA_SCHEDULER_ENABLED defaults False.
    assert sched.PTA_SCHEDULER_ENABLED is False


# --- Tick loop: fires exactly once at the matching minute/day ------------------


def test_scheduled_job_fires_once_at_matching_minute_and_day(monkeypatch, fast_clock):
    monkeypatch.setattr(sched, "PTA_SCHEDULER_TIME", "18:00")
    monkeypatch.setattr(sched, "PTA_SCHEDULER_DAYS", {"MON", "TUE", "WED", "THU", "FRI"})

    calls = []

    async def _fake_run_scheduled():
        calls.append(1)

    monkeypatch.setattr(sched, "_run_scheduled", _fake_run_scheduled)

    tz = ZoneInfo(sched.PTA_SCHEDULER_TZ)
    # 2026-06-03 is a Wednesday.
    matching = datetime(2026, 6, 3, 18, 0, tzinfo=tz)
    fast_clock([matching])

    with pytest.raises(asyncio.CancelledError):
        asyncio.run(sched._scheduled_job())

    assert calls == [1]


